gaf1(){return"\u0623\u062d\u062f \u0627\u0644\u0633\u0637\u0648\u0631 \u0628\u0644\u0627 \u0641\u062d\u0635 \u0645\u062d\u062f\u064e\u0651\u062f. \u0627\u062e\u062a\u0631 \u0627\u0633\u0645 \u0627\u0644\u0641\u062d\u0635\u060c \u0623\u0648 \u0623\u0632\u0644 \u0627\u0644\u0633\u0637\u0631."},
gaeW(){return"\u0625\u062d\u062f\u0649 \u0627\u0644\u0642\u064a\u0645 \u062e\u0627\u0631\u062c \u0627\u0644\u0645\u062f\u0649 \u0627\u0644\u0645\u0645\u0643\u0646 \u0644\u0647\u0630\u0627 \u0627\u0644\u0641\u062d\u0635 \u2014 \u0627\u0644\u0623\u0631\u062c\u062d \u0623\u0646\u0647\u0627 \u0642\u0631\u0627\u0621\u0629 \u062e\u0627\u0637\u0626\u0629. \u0631\u0627\u062c\u0639\u0647\u0627 \u0639\u0644\u0649 \u0627\u0644\u0648\u0631\u0642\u0629."},
gaeY(){return"\xab\u0637\u0628\u064a\u0639\u064a\xbb \u0648\xab\u063a\u064a\u0631 \u0637\u0628\u064a\u0639\u064a\xbb \u062d\u0643\u0645 \u0648\u0644\u064a\u0633 \u0646\u062a\u064a\u062c\u0629 \u0645\u0637\u0628\u0648\u0639\u0629. \u0627\u0643\u062a\u0628 \u0627\u0644\u0646\u062a\u064a\u062c\u0629 \u0643\u0645\u0627 \u0647\u064a \u0645\u0637\u0628\u0648\u0639\u0629 \u0641\u064a \u0627\u0644\u0648\u0631\u0642\u0629."},
gaeV(){return"\u062d\u064f\u0630\u0641 \u0627\u0644\u0645\u0633\u062a\u0646\u062f \u0627\u0644\u0630\u064a \u062c\u0627\u0621\u062a \u0645\u0646\u0647 \u0647\u0630\u0647 \u0627\u0644\u0642\u064a\u0645\u060c \u0641\u0644\u0627 \u064a\u0645\u0643\u0646 \u0625\u0636\u0627\u0641\u062a\u0647\u0627 \u0625\u0644\u0649 \u0633\u062c\u0644\u0651\u0643."},
gaf0(){return"\u0623\u064f\u0636\u064a\u0641\u062a \u0647\u0630\u0647 \u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629 \u0645\u0633\u0628\u0642\u0627\u064b \u0623\u0648 \u0644\u0645 \u062a\u0639\u062f \u0645\u062a\u0627\u062d\u0629. \u0623\u0639\u062f \u0641\u062a\u062d \u0627\u0644\u0634\u0627\u0634\u0629."},
gafK(){return"\u0623\u064f\u0636\u064a\u0641\u062a \u0627\u0644\u0642\u064a\u0645 \u0625\u0644\u0649 \u0633\u062c\u0644\u0651\u0643"},
gafJ(){return"\u0623\u064f\u062e\u0641\u064a\u062a \u0627\u0644\u0642\u064a\u0645\u0629 \u0645\u0646 \u0633\u062c\u0644\u0651\u0643 \u2014 \u0644\u0645 \u062a\u064f\u062d\u0630\u0641\u060c \u0648\u064a\u0645\u0643\u0646 \u0627\u0633\u062a\u0639\u0627\u062f\u062a\u0647\u0627 \u0644\u0627\u062d\u0642\u0627\u064b"},
gafI(){return"\u0623\u064f\u062e\u0641\u064a \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \u0645\u0646 \u0633\u062c\u0644\u0651\u0643 \u2014 \u0644\u0645 \u064a\u064f\u062d\u0630\u0641\u060c \u0648\u064a\u0645\u0643\u0646 \u0627\u0633\u062a\u0639\u0627\u062f\u062a\u0647 \u0644\u0627\u062d\u0642\u0627\u064b"},
afH(a){return"\u0631\u0645\u0632 \u0627\u0644\u062e\u0637\u0623: "+a},
