gann(){return"\u0623\u0639\u062f \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629"},
adq(a,b){return"\u0635\u0641\u062d\u0629 "+a+" \u0645\u0646 "+b},
gaf8(){return"\u0644\u0627 \u064a\u0645\u0643\u0646\u0646\u0627 \u062a\u062d\u062f\u064a\u062f \u0645\u0648\u0636\u0639 \u0647\u0630\u0647 \u0627\u0644\u0642\u064a\u0645\u0629 \u0641\u064a \u0627\u0644\u0635\u0641\u062d\u0629 \u2014 \u062a\u062d\u0642\u0651\u0642 \u0645\u0646\u0647\u0627 \u0628\u0646\u0641\u0633\u0643 \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u062a\u0646\u062f"},
