gTd(){return"\u0631\u0627\u062c\u0639\u0647\u0627 \u0627\u0644\u0622\u0646"},
gadr(){return"\u0627\u0644\u0635\u0641\u062d\u0629 \u0627\u0644\u0633\u0627\u0628\u0642\u0629"},
