gafu(){return"\u0623\u0636\u0650\u0641 \u0627\u0644\u0642\u064a\u0645 \u0627\u0644\u062a\u064a \u0623\u0643\u0651\u062f\u062a\u0647\u0627 \u0625\u0644\u0649 \u0633\u062c\u0644\u0651\u0643 \u0627\u0644\u0637\u0628\u064a"},
gaf7(){return"\u062a\u062e\u0631\u062c \u062f\u0648\u0646 \u062d\u0641\u0638\u061f"},
gaf4(){return"\u0633\u062a\u064f\u0644\u063a\u0649 \u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a\u0643 (\u2713 \u0648 \u2717) \u0639\u0644\u0649 \u0647\u0630\u0647 \u0627\u0644\u0635\u0641\u062d\u0629\u060c \u0648\u0644\u0646 \u064a\u064f\u0636\u0627\u0641 \u0634\u064a\u0621 \u0625\u0644\u0649 \u0633\u062c\u0644\u0651\u0643. \u0627\u0644\u0648\u062b\u064a\u0642\u0629 \u062a\u0628\u0642\u0649 \u0641\u064a \u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629\u060c \u0648\u064a\u0645\u0643\u0646\u0643 \u0627\u0644\u0628\u062f\u0621 \u0645\u0646 \u062c\u062f\u064a\u062f \u0644\u0627\u062d\u0642\u0627\u064b."},
gaf5(){return"\u0627\u062e\u0631\u062c \u0648\u0623\u0644\u063a\u0650 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a"},
gaf6(){return"\u0623\u0643\u0645\u0644 \u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629"},
