gZA(){return"\u0645\u0631\u062d\u0628\u0627\u064b \u0628\u0639\u0648\u062f\u062a\u0643"},
gZB(){return"\u0646\u0633\u062a\u062e\u062f\u0645 \u062d\u0633\u0627\u0628 Google \u0644\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644 \u0641\u0642\u0637 \u2014 \u0644\u0627 \u0646\u0637\u0651\u0644\u0639 \u0639\u0644\u0649 \u0628\u0631\u064a\u062f\u0643 \u0648\u0644\u0627 \u062c\u0647\u0627\u062a \u0627\u062a\u0635\u0627\u0644\u0643."},
ga5M(){return"\u0627\u0641\u062a\u062d \u0633\u062c\u0644\u0651\u0643"},
