gaiB(){return"\u0628\u06d5\u0647\u0627"},
gaid(){return"\u0645\u06d5\u0648\u062f\u0627\u06cc \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc\u062f\u0627\u0631 \u0628\u06d5 \u062c\u06ce\u06af\u06cc\u0631\u06cc \u0644\u06d5 \u06a9\u0627\u062a\u0627\u0644\u06c6\u06af\u06cc \u062a\u0627\u0642\u06cc\u06af\u06d5\u0648\u06d5 \u062f\u06ce\u062a \u2014 \u0647\u06d5\u0631\u06af\u06cc\u0632 \u0628\u06d5 \u062f\u06d5\u0633\u062a \u0646\u0627\u0646\u0648\u0648\u0633\u0631\u06ce\u062a\u060c \u0648 \u0647\u06d5\u0631\u06af\u06cc\u0632 \u0628\u06d5\u062a\u0627\u06b5 \u0646\u0627\u0645\u06ce\u0646\u06ce\u062a\u06d5\u0648\u06d5."},
